#!/usr/bin/env python3
"""One button on the review screen: "Refresh from Xtrium and re-check".
It asks Xtrium for the SOP and category again, runs the system checks against it, and shows what changed (including checks the
current SOP no longer makes, which are withdrawn). It sits in the toolbar and inside the "things to settle with this SOP" box.
Run from the repo root. Safe to run twice."""
import os, sys, json, zlib, base64
sys.stdout.reconfigure(errors='replace')
SYNC = json.loads('{"frontend/src/components/enh/ReviewWorkspace.tsx": "", "frontend/src/components/enh/ReviewSidePanel.tsx": ""}')
OLD = 'scan: (sourceId: string) => api.post(`/quality/sources/${sourceId}/scan`).then(r => r.data as { created: number; records: number; sop_checked?: boolean }),'
NEW = 'scan: (sourceId: string) => api.post(`/quality/sources/${sourceId}/scan`).then(r => r.data as { created: number; withdrawn?: number; records: number; sop_checked?: boolean }),'
ok = True

def rd(p):
    raw = open(p, 'rb').read().decode('utf-8'); return raw, ('\r\n' in raw), raw.replace('\r\n', '\n')
def wr(p, t, crlf): open(p, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8'))

for path, b in SYNC.items():
    new = zlib.decompress(base64.b64decode(b))
    if os.path.exists(path):
        old, crlf, t = rd(path)
        if t.encode('utf-8') == new: print("same      ", path); continue
        bk = os.path.join(os.path.expanduser("~/xtrium_backup_60"), path)
        os.makedirs(os.path.dirname(bk), exist_ok=True); open(bk, 'wb').write(old.encode('utf-8'))
        verb = "replaced  "
    else:
        crlf = False; verb = "created   "; os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    wr(path, new.decode('utf-8'), crlf); print(verb, path)

p = "frontend/src/api/client.ts"
if not os.path.exists(p): print("MISSING   ", p); ok = False
else:
    raw, crlf, t = rd(p)
    if "withdrawn?: number" in t: print("already    client.ts scan type")
    elif t.count(OLD) != 1: print("NO MATCH   client.ts scan type"); ok = False
    else: wr(p, t.replace(OLD, NEW, 1), crlf); print("applied    client.ts scan type")
print()
print("All applied." if ok else "Some edits did not match: paste the lines above and I will fit them to your files.")
